import { useEffect, useState } from "react";
import surahs from "@/data/surahs.json";

/**
 * Quran data access.
 * Verse text comes ONLY from /public/quran/*.json, which is generated byte-for-byte
 * from a verified Uthmani source by scripts/import-quran.mjs and checked by
 * scripts/verify-quran.mjs. Never construct or edit verse text in code.
 */

export interface SurahMeta {
  id: number;
  name: string;
  transliteration: string;
  type: "meccan" | "medinan";
  verses: number;
}
interface Verse {
  id: number;
  text: string;
}
export interface Surah {
  id: number;
  name: string;
  verses: Verse[];
}

export const SURAHS = surahs as SurahMeta[];
export const surahMeta = (id: number) => SURAHS[id - 1];

/** Base path for data files; the standalone preview build overrides it. */
const DATA_BASE: string = (globalThis as { __RIFQ_DATA_BASE__?: string }).__RIFQ_DATA_BASE__ ?? "";

const cache = new Map<number, Promise<Surah>>();

export function loadSurah(id: number): Promise<Surah> {
  if (!cache.has(id)) {
    const p = fetch(`${DATA_BASE}/quran/${id}.json`).then((r) => {
      if (!r.ok) throw new Error(`Failed to load surah ${id}`);
      return r.json() as Promise<Surah>;
    });
    p.catch(() => cache.delete(id));
    cache.set(id, p);
  }
  return cache.get(id)!;
}

export function useSurah(id: number | null) {
  const [data, setData] = useState<Surah | null>(null);
  const [error, setError] = useState<string | null>(null);
  useEffect(() => {
    if (id == null) return;
    let alive = true;
    setData(null);
    setError(null);
    loadSurah(id)
      .then((s) => alive && setData(s))
      .catch(() => alive && setError("تعذّر تحميل السورة. تحقّق من الاتصال وحاول مرة أخرى."));
    return () => {
      alive = false;
    };
  }, [id]);
  return { surah: data, error };
}

export function useSurahs(ids: number[]) {
  const [map, setMap] = useState<Record<number, Surah>>({});
  const key = ids.join(",");
  useEffect(() => {
    let alive = true;
    Promise.all(key.split(",").filter(Boolean).map((i) => loadSurah(Number(i))))
      .then((list) => alive && setMap(Object.fromEntries(list.map((s) => [s.id, s]))))
      .catch(() => {});
    return () => {
      alive = false;
    };
  }, [key]);
  return map;
}

/**
 * Words of a verse, obtained only by splitting the verified string on spaces.
 * Joining them with a single space reproduces the original string exactly.
 */
export function words(text: string): string[] {
  return text.split(" ");
}

/** Surahs that open without a separate Basmala header. */
export const showBasmalaHeader = (surahId: number) => surahId !== 1 && surahId !== 9;

// ---------- Audio (verified recitations streamed from EveryAyah.com) ----------

export interface Reciter {
  id: string;
  name: string;
  folder: string;
}

export const RECITERS: Reciter[] = [
  { id: "alafasy", name: "مشاري راشد العفاسي", folder: "Alafasy_128kbps" },
  { id: "husary", name: "محمود خليل الحصري", folder: "Husary_128kbps" },
  { id: "minshawi", name: "محمد صديق المنشاوي", folder: "Minshawy_Murattal_128kbps" },
];

const pad = (n: number) => String(n).padStart(3, "0");
export const audioUrl = (surah: number, ayah: number, reciter: Reciter = RECITERS[0]) =>
  `https://everyayah.com/data/${reciter.folder}/${pad(surah)}${pad(ayah)}.mp3`;

export const toArabicDigits = (n: number | string) =>
  String(n).replace(/\d/g, (d) => "٠١٢٣٤٥٦٧٨٩"[Number(d)]);

/** Al-Fatihah plus all of Juz' Amma (An-Nas back to An-Naba), used by children's activities. */
const KIDS_SURAHS = [1, ...Array.from({ length: 37 }, (_, i) => 114 - i)];

/** Surah pickers: the children's surahs first (Al-Fatiha, then Juz' Amma from An-Nas), then the rest. */
export const PICKER_SURAHS: SurahMeta[] = (() => {
  const kids = new Set(KIDS_SURAHS);
  return [...KIDS_SURAHS.map((id) => SURAHS[id - 1]), ...SURAHS.filter((s) => !kids.has(s.id))];
})();
